async function readApiResponse(response) {
  const contentType=response.headers.get('content-type')||'';
  if(!contentType.includes('application/json')) throw new Error(response.ok?'Authentication server returned an invalid response.':'Authentication server is unavailable. Please restart the backend.');
  const body=await response.json();
  if(response.status===401&&localStorage.getItem('abit_session')){
    localStorage.removeItem('abit_session');
    setTimeout(()=>window.location.reload(),0);
  }
  return body;
}

