  const restore=async row=>{try{const token=localStorage.getItem('abit_session'),response=await fetch(`/api/subject-teacher-allocations/${row.id}/restore`,{method:'POST',headers:{Authorization:`Bearer ${token}`}}),body=await readApiResponse(response);if(!response.ok)throw new Error(body.message);setMessage(body.message);await load();}catch(err){setError(err.message);}};
