function StudentModulePlaceholder({title}){
  if(title==='Student Attendance Report')return <StudentAttendanceReport/>;
  if(title==='Attendance Entry Report')return <AttendanceEntryReport/>;
  if(title==='Subject-wise Attendance Report')return <SubjectWiseAttendanceReport/>;
  if(title==='Lesson Plans Report')return <LessonPlansReport/>;
  if(title==='Assign Class Teacher')return <AssignClassTeacherPage/>;
  if(title==='Allot Substitute Teacher')return <AllotSubstituteTeacherPage/>;
  if(title==='Take Attendance')return <TakeAttendancePage/>;
  if(title==='Student Attendance')return <StudentAttendancePage/>;
  if(title==='Calendar Setting')return <AttendanceCalendarSettingPage/>;
  if(title==='Permissions')return <UserPermissionManagementPage/>;
  if(title==='Message')return <DashboardMessagePage/>;
  if(title==='Notice')return <DashboardNoticePage/>;
  if(title==='Lecture Notes'||title==='Material Upload')return <MaterialUploadPage/>;
  if(title==='Course Coverage Report')return <CourseCoverageReportPage/>;
  if(title==='Lesson Plan Report')return <LessonPlanReportPage/>;
  return <section className="employee-module-placeholder"><span><Icon name="users" size={28}/></span><h2>{title}</h2><p>This Student module is ready for its management screen.</p></section>;
}

