    <section className="student-form-section"><header><h3>Initial Batch</h3></header><div>{input('Batch Name *','batchName',{placeholder:'2026-2030',required:true})}{input('Batch Alias','batchAlias',{placeholder:'2026'})}{input('Admission Year *','admissionYear',{type:'number',min:'2000',max:'2100',required:true})}{input('Start Date *','startDate',{type:'date',required:true})}{input('End Date *','endDate',{type:'date',required:true})}{input('Approved Intake *','approvedIntake',{type:'number',min:'0',required:true})}{input('Lateral Entry Intake','lateralEntryIntake',{type:'number',min:'0'})}</div></section>
