        <label><span>Department</span><select value={filters.departmentId} onChange={e=>setFilters({...filters,departmentId:e.target.value})}><option value="">All Departments</option>{options.departments.map(item=><option value={item.id} key={item.id}>{item.code} — {item.name}</option>)}</select></label>
