  const [filters,setFilters]=useState(initialFilters);const [rows,setRows]=useState([]);const [departments,setDepartments]=useState([]);const [issueTypes,setIssueTypes]=useState([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');
  const load=(next=filters)=>{setLoading(true);setError('');const token=localStorage.getItem('abit_session');const params=new URLSearchParams({asOn:next.asOn,overdueOnly:String(next.overdueOnly)});if(next.memberType)params.set('memberType',next.memberType);if(next.departmentId)params.set('departmentId',next.departmentId);if(next.issueTypeId)params.set('issueTypeId',next.issueTypeId);fetch(`/api/library/reports/return-pending?${params}`,{headers:{Authorization:`Bearer ${token}`}}).then(async response=>{const data=await readApiResponse(response);if(!response.ok)throw new Error(data.message);return data;}).then(data=>{setRows(data.rows||[]);setDepartments(data.departments||[]);setIssueTypes(data.issueTypes||[]);}).catch(err=>setError(err.message)).finally(()=>setLoading(false));};
