  const remove=async item=>{if(!window.confirm(`Delete the ${item.material_name} price effective ${String(item.effective_from).slice(0,10)}?`))return;try{const token=localStorage.getItem('abit_session');const response=await fetch(`/api/library/study-material-prices/${item.id}`,{method:'DELETE',headers:{Authorization:`Bearer ${token}`}});const data=await readApiResponse(response);if(!response.ok)throw new Error(data.message);if(editId===item.id)clear();setMessage(data.message);await load();}catch(err){setError(err.message);}};
