  const downloadTemplate=()=>{const content='Subject Code,Subject Name,Subject Alias,Department,Status\r\nSUB0001,Computer Science,CS,CSE,Active';const url=URL.createObjectURL(new Blob([content],{type:'text/csv'}));const link=document.createElement('a');link.href=url;link.download='subject-import-template.csv';link.click();URL.revokeObjectURL(url);};
  const chooseImport=async e=>{const file=e.target.files[0];setImportFile(file?.name||'');setImportRows([]);setMessage('');setError('');if(!file)return;try{const lines=(await file.text()).replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);const headers=lines.shift().split(',').map(value=>value.replace(/^"|"$/g,'').trim().toLowerCase());const rows=lines.map(line=>{const values=line.split(',').map(value=>value.replace(/^"|"$/g,'').trim());const get=key=>values[headers.indexOf(key)]||'';return {code:get('subject code'),name:get('subject name'),alias:get('subject alias'),department:get('department'),status:get('status')};});if(!rows.length)throw new Error('The selected file has no data rows.');setImportRows(rows);}catch(err){setError(`Import file: ${err.message}`);}};
  const importExcel=async()=>{setSaving(true);setMessage('');setError('');try{const token=localStorage.getItem('abit_session');const response=await fetch('/api/library/subjects/bulk',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({rows:importRows})});const data=await readApiResponse(response);if(!response.ok)throw new Error(data.message);setMessage(data.message);setImportRows([]);setImportFile('');await load();}catch(err){setError(err.message);}finally{setSaving(false);}};
