function getInstituteLocation(){
  try{
    const profile=JSON.parse(localStorage.getItem('abit_institute_profile')||'null')||{};
    const address=[profile.addressLine1,profile.addressLine2,profile.city,profile.district,profile.state,profile.country,profile.pinCode].filter(Boolean).join(', ');
    return {name:profile.instituteName||'ABIT Group of Institutions',address:address||'ABIT Group of Institutions, Cuttack, Odisha, India'};
  }catch{return {name:'ABIT Group of Institutions',address:'ABIT Group of Institutions, Cuttack, Odisha, India'};}
}
function getWeekNumber(date){
  const current=new Date(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate()));
  const start=new Date(Date.UTC(date.getFullYear(),0,1));
  return Math.ceil((((current-start)/86400000)+start.getUTCDay()+1)/7);
}
function ordinal(value){
  const mod100=value%100;
  if(mod100>=11&&mod100<=13)return `${value}th`;
  return `${value}${value%10===1?'st':value%10===2?'nd':value%10===3?'rd':'th'}`;
}
function Calendar({date}){
  const year=date.getFullYear(),month=date.getMonth();
  const firstDay=new Date(year,month,1).getDay();
  const daysInMonth=new Date(year,month+1,0).getDate();
  const daysInPreviousMonth=new Date(year,month,0).getDate();
  const cells=Array.from({length:42},(_,index)=>{
    const day=index-firstDay+1;
    if(day<1)return {day:daysInPreviousMonth+day,muted:true};
    if(day>daysInMonth)return {day:day-daysInMonth,muted:true};
    return {day,muted:false};
  });
  const heading=date.toLocaleDateString('en-IN',{month:'long',year:'numeric'});
  return <div className="calendar"><header><span/><b>{heading}</b><span/></header><div className="calendar-grid">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=><small key={d}>{d}</small>)}{cells.map((cell,index)=><span className={`${cell.muted?'muted':''} ${!cell.muted&&cell.day===date.getDate()?'today':''}`} key={index}>{cell.day}</span>)}</div></div>
}

